/** Browser caching is explicit for private images; personalized app responses never enter shared caches. */
export function applyAppCachePolicy(request: Request, response: Response): Response {
	const path = new URL(request.url).pathname;
	const setsCookie = response.headers.has('Set-Cookie');
	// Metadata routes are generated by the Worker, so Static Assets' _headers
	// does not apply to this non-versioned manifest.
	if (path === '/manifest.webmanifest' && response.ok && !setsCookie) {
		const headers = new Headers(response.headers);
		headers.set('Cache-Control', 'no-cache');
		return new Response(response.body, {status: response.status, statusText: response.statusText, headers});
	}
	if (path.startsWith('/_next/static/') && !setsCookie && (response.ok || response.status === 304)) return response;
	const type = response.headers.get('Content-Type') ?? '';
	const page = type.includes('text/html') || type.includes('text/x-component') || ['/', '/login', '/setup'].includes(path);
	const privateApi = path.startsWith('/api/') && path !== '/api/branding/icon';
	const cache = response.headers.get('Cache-Control') ?? '';
	// Explicit private browser caches (avatars, attachment previews) remain useful,
	// but must vary across logins even if a handler omitted those request headers.
	if (privateApi && !page && !setsCookie && /^private(?:,|$)/i.test(cache)) {
		const vary = new Set((response.headers.get('Vary') ?? '').split(',').map(v => v.trim().toLowerCase()));
		if (vary.has('cookie') && vary.has('authorization')) return response;
		const headers = new Headers(response.headers);
		headers.append('Vary', 'Cookie, Authorization');
		return new Response(response.body, {status: response.status, statusText: response.statusText, headers});
	}
	if (!page && !privateApi && !setsCookie && !path.startsWith('/_next/static/')) return response;
	const headers = new Headers(response.headers);
	headers.set('Cache-Control', 'private, no-store');
	return new Response(response.body, {status: response.status, statusText: response.statusText, headers});
}
